// Prepare auth request data
// firm_id is now required by the shared ksef-auth webhook (D1/D2 tenancy fix) -
// this is a placeholder for manual testing only. Set it to the actual firm_id
// that owns NIP 1111111111 in your local DB before running this workflow.
return [{
  json: {
    client_nip: '1111111111',
    firm_id: 1 /* TODO: verify this matches your local test firm */
  }
}];

const authResult = $('Authenticate with KSeF').first().json;
const allCerts = $input.all().map(item => item.json);

// Find the SymmetricKeyEncryption certificate (needed for session encryption)
let certEntry = allCerts.find(c => c.usage && c.usage.includes('SymmetricKeyEncryption'));
if (!certEntry) throw new Error('SymmetricKeyEncryption certificate not found! Available usages: ' + JSON.stringify(allCerts.map(c => c.usage)));

const certBase64 = certEntry.certificate;

// Wrap in PEM format
const pemCert = '-----BEGIN CERTIFICATE-----\n' + certBase64.match(/.{1,64}/g).join('\n') + '\n-----END CERTIFICATE-----';

// AES-256 key + IV generation and RSA-OAEP-SHA256 wrapping is done by the
// XAdES sidecar, not here - was previously duplicated locally via Node's
// crypto module, which bypassed the sidecar entirely (a second, independent
// implementation of the same operation that could drift from it - found in
// a 2026-09-13 audit).
const sidecarUrl = $env.XADES_SIDECAR_URL || 'http://xades-sidecar:8090';
const keyResp = await $helpers.httpRequest({
  method: 'POST',
  url: `${sidecarUrl}/generate-session-key`,
  headers: { 'X-Sidecar-Api-Key': $env.SIDECAR_API_KEY },
  body: { ksefPublicKeyPem: pemCert },
  json: true,
});

if (!keyResp.success) {
  throw new Error('Sidecar generate-session-key failed: ' + (keyResp.error || 'unknown error'));
}

return [{
  json: {
    access_token: authResult.accessToken,
    aes_key_hex: Buffer.from(keyResp.keyBase64, 'base64').toString('hex'),
    iv_hex: Buffer.from(keyResp.ivBase64, 'base64').toString('hex'),
    encrypted_symmetric_key: keyResp.encryptedKeyBase64,
    initialization_vector: keyResp.ivBase64,
    cert_usage: certEntry.usage,
    cert_valid_from: certEntry.validFrom,
    cert_valid_to: certEntry.validTo
  }
}];

const invoiceResult = $input.first().json;
const keyData = $('Generate AES Key & Encrypt').first().json;
const sessionData = $('Open Interactive Session').first().json;

return [{
  json: {
    session_reference: sessionData.referenceNumber,
    invoice_reference: invoiceResult.referenceNumber,
    access_token: keyData.access_token
  }
}];

// Simple delay - wait 5 seconds for KSeF to process the invoice
await new Promise(resolve => setTimeout(resolve, 5000));
return $input.all();

const invoiceStatus = $('Check Invoice Status').first().json;
const closeResult = $input.first().json;
const sessionRef = $('Prepare Status Check').first().json.session_reference;
const invoiceRef = $('Prepare Status Check').first().json.invoice_reference;

return [{
  json: {
    success: true,
    message: 'Test invoice submitted successfully!',
    session_reference: sessionRef,
    invoice_reference: invoiceRef,
    invoice_status: invoiceStatus,
    session_closed: closeResult
  }
}];

const error = $input.first().json;
return [{
  json: {
    error_type: 'invoice_submit_error',
    message: error.message || error.execution?.error?.message || 'Unknown error',
    workflow: 'KSeF - Submit Test Invoice',
    timestamp: new Date().toISOString()
  }
}];
